//! An owned head direction must not depend on the actor's world translation.
//! Keep the native resource refresh, then rotate the cardinal vector with the
//! same native quaternion routine, before its two translated f32 points lose
//! precision on subtraction. Only the current head composition may opt in.
use super::rotation_precision::Snapshot;
pub(super) type Direction = unsafe extern "thiscall" fn(usize,usize,i32,usize)->usize;
pub(super) type Rotate = unsafe extern "thiscall" fn(usize,usize,usize)->usize;

fn quaternion(t:Snapshot,component:usize,index:i32,read:&impl Fn(usize,usize)->Option<u32>)->Option<[f32;4]> {
    let pawn=t.owner.pawn;
    let hands=read(pawn,0x12ac)? as usize;
    if hands==0 || read(hands,0)?!=0x2a23634 || read(hands,0x310)? as usize!=pawn
        || read(hands,0x144)? as usize!=t.owner.world {return None;}
    let instance=read(hands,0x1f0)? as usize;
    let expected=if instance!=0 {read(instance,0xc0)? as usize} else {
        let fallback=read(hands,0x1f8)? as usize;
        if fallback==0{return None;} read(fallback,0x60)? as usize
    };
    if expected==0 || component!=expected || !(0..=4096).contains(&index) {return None;}
    let mapping=read(hands,0x430)? as usize;
    if mapping==0 || read(mapping,14*4)? as i32!=index{return None;}
    let worker=read(0x3301820,0)? as usize;
    // Native 1D21CA0/1CE27D0 use AC4 in phases 0..=8 and 10.
    // Keep unknown phases native; retain every current-owner/palette guard.
    if worker==0 || !matches!(read(worker,8)?,0..=8|10){return None;}
    let palette=read(component,0xac4)? as usize;
    if palette==0{return None;}
    let bone=palette.checked_add((index as usize).checked_mul(48)?)?;
    let mut q=[0.;4];
    for i in 0..4 {q[i]=f32::from_bits(read(bone,i*4)?);}
    let norm=q.iter().map(|x|x*x).sum::<f32>();
    if q.iter().any(|x|!x.is_finite()) || !(0.99..=1.01).contains(&norm){return None;}
    Some(q)
}

pub(super) unsafe fn direction(component:usize,out:usize,index:i32,input:usize,
    context:impl Fn()->Option<Snapshot>, read:impl Fn(usize,usize)->Option<u32>,
    readable:impl Fn(usize,usize)->bool, native:Direction, rotate:Rotate)->usize {
    let before=context();
    // Preserve refresh, return value and all foreign/non-owned native calls.
    let result=native(component,out,index,input);
    let Some(token)=before else{return result;};
    if result!=out || context()!=Some(token) || !readable(out,12) || !readable(input,12){return result;}
    let v=(input as *const [f32;3]).read_unaligned();
    if v!=[1.,0.,0.] && v!=[0.,1.,0.] && v!=[0.,0.,1.] {return result;}
    let Some(q)=quaternion(token,component,index,&read) else{return result;};
    let mut precise=[0.0f32;3];
    if rotate(q.as_ptr() as usize,precise.as_mut_ptr() as usize,v.as_ptr() as usize)==precise.as_ptr() as usize
        && precise.iter().all(|x|x.is_finite()) {
        (out as *mut [f32;3]).write_unaligned(precise);
    }
    result
}

/// AFA950 removes the actor basis from the current quaternion palette before
/// applying local head animation. Its old 5355E0 inverse uses four-unit lookup
/// bins, unlike the native quaternion palette producer. Keep the native call,
/// but use the same actor integer angles without lookup quantization here. The
/// fractional input is already applied by camera_input; do not add it twice.
pub(super) type Inverse = unsafe extern "thiscall" fn(usize,i32,i32,i32)->usize;
pub(super) unsafe fn inverse_basis(out:usize, rotation:[i32;3],
    context:impl Fn()->Option<Snapshot>, read:impl Fn(usize,usize)->Option<u32>,
    readable:impl Fn(usize,usize)->bool, native:Inverse)->usize {
    fn owned(t:Snapshot,r:[i32;3],read:&impl Fn(usize,usize)->Option<u32>)->Option<usize>{
        let worker=read(0x3301820,0)? as usize;
        if worker==0 || !matches!(read(worker,8)?,0..=8|10){return None;}
        let hands=read(t.owner.pawn,0x12ac)? as usize;
        if hands<0x10000 || read(hands,0)?!=0x2a23634
            || read(hands,0x310)? as usize!=t.owner.pawn
            || read(hands,0x144)? as usize!=t.owner.world
            || (0..3).any(|i|read(hands,0xa8+i*4).map(|x|x as i32)!=Some(r[i])) {return None;}
        Some(hands)
    }
    let before=context().and_then(|t|owned(t,rotation,&read).map(|h|(t,h)));
    let result=native(out,rotation[0],rotation[1],rotation[2]);
    let Some((t,hands))=before else{return result;};
    if result!=out || context()!=Some(t) || !readable(out,64)
        || owned(t,rotation,&read)!=Some(hands) {return result;}
    if let Some(forward)=super::rotation_camera::input_matrix(rotation,[0.;2]) {
        let inverse:[f32;16]=std::array::from_fn(|i|forward[i%4*4+i/4]);
        (out as *mut [f32;16]).write_unaligned(inverse);
    }
    result
}

